mapper.select:
SELECT * FROM (
	SELECT Tb.*, rownum rNum FROM (
		SELECT * FROM mileage
		WHERE 1=1
		
			AND type =
			
				
				'minus'
				
				
				'plus'
				
				
				type
				
			
		
		
			AND created_date BETWEEN TO_DATE(#{sh_s_date}, 'YYYY-MM-DD')
								 AND TO_DATE(#{sh_e_date}, 'YYYY-MM-DD') + 1 - INTERVAL '1' SECOND
		
		
			AND MemberId=#{memberId}
		
		ORDER BY mileage_no DESC
	) Tb
)
WHERE rNum >= #{start}
AND rNum <= #{end}

mapper.insert:
DECLARE
next_no NUMBER;
BEGIN
getnext_mileage_no(next_no);
INSERT INTO mileage (mileage_no, MemberId, mileage_name, type, points, created_date)
VALUES (next_no, #{memberId}, #{mileage_name}, 'plus', #{points}, CURRENT_TIMESTAMP);
END;

